export const DICT: Record<Lang, Dict> = { en, de, fr, es, it, nl };

export const LOCALES: Record<Lang, string> = { en: 'en-GB', de: 'de-DE', fr: 'fr-FR', es: 'es-ES', it: 'it-IT', nl: 'nl-NL' };

export function translate(lang: Lang, key: string, params?: Record<string, string | number>): string {
  if (key === 'common.photos' && params?.n === 1) key = 'common.photo';
  let s = DICT[lang]?.[key] ?? en[key] ?? key;
  if (params) for (const [k, v] of Object.entries(params)) s = s.split(`{${k}}`).join(String(v));
  return s;
}
